import {validateBackup} from './backup.js';
import {makeDeck,reviewSummary} from './repetition.js';
import {readAll,getRecord,putRecord,saveGame,personalStats,THEMES} from './archive.js';
import {escapeHTML as esc} from './settings.js';
import {fetchProfile,syncArchive} from './chess-api.js';
import {Chess} from './vendor/chess.js';
const $=id=>document.getElementById(id);let games=[],page=0,profile=null,controller=null;
const date=t=>new Date(t).toLocaleDateString('it-IT'),fixed=x=>x==null?'—':x.toFixed(1);
function stats(){const s=personalStats(games);$('stats').innerHTML=[['Partite registrate',s.total],['Vinte / patte / perse',`${s.wins} / ${s.draws} / ${s.losses}`],['Precisione media',fixed(s.accuracy)],['Analisi personali complete',s.analyzed]].map(([label,value])=>`<div class="stat"><span>${label}</span><strong>${value}</strong></div>`).join('');const values=s.averages.slice(-20);$('trend').innerHTML=values.length?`<div class="trend-bars" role="img" aria-label="Precisione delle ultime ${values.length} partite analizzate">${values.map(v=>`<div title="${date(v.date)}: ${v.value.toFixed(1)}"><span>${v.value.toFixed(0)}</span><i style="height:${Math.max(3,v.value)}px"></i><small>${date(v.date).slice(0,5)}</small></div>`).join('')}</div>`:'<p>Analizza una partita e indica il tuo colore per iniziare.</p>';$('trendNote').textContent=(s.delta===null?'Servono 10 analisi personali complete per confrontare le ultime 5 con le 5 precedenti.':`Ultime 5 rispetto alle 5 precedenti: ${s.delta>=0?'+':''}${s.delta.toFixed(1)} punti di precisione. Non è una misura del tuo Elo.`)+` ${s.total-s.identified} partite senza colore personale. Esiti calcolati su ${s.finished} partite concluse.`;const entries=Object.entries(s.themes).sort((a,b)=>b[1]-a[1]);$('themes').innerHTML=entries.some(([,n])=>n)?entries.map(([key,n])=>`<div class="theme-row"><span>${THEMES[key]}</span><strong>${n}</strong></div>`).join(''):'<p>Nessun errore personale ancora disponibile. Le partite importate vanno prima analizzate.</p>'}
function list(){const q=$('gameSearch').value.toLowerCase(),source=$('sourceFilter').value;const filtered=games.filter(g=>(source==='all'||g.source===source)&&JSON.stringify(g.headers).toLowerCase().includes(q)).sort((a,b)=>b.playedAt-a.playedAt);page=Math.min(page,Math.max(0,Math.ceil(filtered.length/15)-1));const slice=filtered.slice(page*15,page*15+15);$('archiveList').innerHTML=slice.length?slice.map(g=>`<article class="archive-row"><div><strong>${esc(g.headers.White||'Bianco')} <span class="muted">vs</span> ${esc(g.headers.Black||'Nero')}</strong><p>${date(g.playedAt)} · ${esc(g.source)} · ${esc(g.headers.Result||'*')} · ${g.analysis?.complete?'Analizzata':'Da completare / analizzare'}</p></div><button class="secondary" data-open-game="${esc(g.id)}">Apri →</button></article>`).join(''):'<div class="empty-state"><h3>Qui comincia il tuo archivio.</h3><p>Gioca con il coach, importa un PGN o collega un profilo Chess.com.</p><a href="coach.html">Gioca una partita →</a></div>';$('pageInfo').textContent=`${filtered.length} partite · pagina ${page+1} / ${Math.max(1,Math.ceil(filtered.length/15))}`;$('previousPage').disabled=page===0;$('nextPage').disabled=(page+1)*15>=filtered.length;document.querySelectorAll('[data-open-game]').forEach(b=>b.onclick=()=>{const g=games.find(g=>g.id===b.dataset.openGame);try{localStorage.setItem('plystreak-review-import',g.pgn);localStorage.setItem('plystreak-review-id',g.id);localStorage.setItem('plystreak-review-side',g.side||'');location.href='index.html?training=1'}catch{$('hubStatus').textContent='Memoria temporanea non disponibile. Esporta il backup e conserva i PGN.'}})}
async function refresh(){games=await readAll();stats();list();try{const r=await fetch('vendor/training-catalog.json');if(!r.ok)throw Error('Catalogo non disponibile');const deck=makeDeck(games,await r.json()),s=reviewSummary(deck.cards,await readAll('attempts'));$('reviewOverview').textContent=`${s.due} da ripassare · ${s.new} nuove posizioni · ${s.mastered} consolidate. Le riuscite senza aiuti allungano gli intervalli.`}catch{$('reviewOverview').textContent='Apri Esercizi per vedere il tuo piano di ripasso.'}}
function showProfile(){if(!profile){$('ratings').innerHTML='';$('syncGames').disabled=true;return}$('username').value=profile.username;$('ratings').innerHTML=['rapid','blitz','bullet','daily'].map(type=>`<div class="stat"><span>${type}</span><strong>${profile.stats['chess_'+type]?.last?.rating??'—'}</strong></div>`).join('');$('syncGames').disabled=false;$('syncStatus').textContent=`Profilo ${profile.username} · letto il ${new Date(profile.fetchedAt).toLocaleString('it-IT')}. Rating pubblico Chess.com; può non essere in tempo reale.`}
$('username').oninput=()=>{$('syncGames').disabled=!profile||$('username').value.trim().toLowerCase()!==profile.username};
$('connectForm').onsubmit=async e=>{e.preventDefault();$('connect').disabled=true;$('syncStatus').textContent='Lettura del profilo pubblico…';try{profile=await fetchProfile($('username').value.trim());await putRecord(profile,'meta');localStorage.setItem('plystreak-chess-user',profile.username);showProfile()}catch(e){$('syncStatus').textContent=e.message}finally{$('connect').disabled=false}};
$('syncGames').onclick=async()=>{if(!profile||controller)return;controller=new AbortController();$('syncGames').disabled=true;$('connect').disabled=true;$('disconnect').disabled=true;$('cancelSync').hidden=false;try{const r=await syncArchive(profile.username,$('syncRange').value,async records=>{let added=0;for(const record of records){await saveGame(record);added++}return added},controller.signal,(i,n,m)=>$('syncStatus').textContent=`Importazione mese ${i+1}/${n} · ${m}. Le partite già presenti non vengono duplicate.`);$('syncStatus').textContent=`Importazione completata: ${r.count} partite lette in ${r.months} mesi; ${r.skipped} partite non standard escluse.`}catch(e){$('syncStatus').textContent=e.message+' I mesi già scaricati rimangono disponibili.'}finally{controller=null;$('syncGames').disabled=false;$('connect').disabled=false;$('disconnect').disabled=false;$('cancelSync').hidden=true;await refresh()}};
$('cancelSync').onclick=()=>controller?.abort();$('disconnect').onclick=async()=>{if(controller)return;profile=null;await putRecord({id:'chess-profile',disconnected:true},'meta');localStorage.removeItem('plystreak-chess-user');showProfile();$('syncStatus').textContent='Profilo scollegato. Le partite già importate restano nell’archivio.'};
$('gameSearch').oninput=()=>{page=0;list()};$('sourceFilter').onchange=()=>{page=0;list()};$('previousPage').onclick=()=>{page--;list()};$('nextPage').onclick=()=>{page++;list()};
$('backup').onclick=async()=>{const backup={format:'plystreak-backup',version:1,games:await readAll(),attempts:await readAll('attempts')};const url=URL.createObjectURL(new Blob([JSON.stringify(backup)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='plystreak-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)};
$('restore').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>50000000)throw Error('Il backup supera 50 MB.');const data=validateBackup(JSON.parse(await f.text()));for(const g of data.games)if(!await getRecord(g.id))await saveGame(g);for(const a of data.attempts)if(!await getRecord(a.id,'attempts'))await putRecord(a,'attempts');$('hubStatus').textContent='Backup ripristinato: partite, analisi e ripassi. I record già presenti sono stati conservati.';await refresh()}catch(e){$('hubStatus').textContent=e.message}e.target.value=''};
(async()=>{try{await refresh();const p=await getRecord('chess-profile','meta');if(p&&!p.disconnected){profile=p;showProfile()}}catch(e){$('hubStatus').textContent=e.message}})();
